    retention_run_id BINARY(16) NOT NULL,
    data_type VARCHAR(64) NOT NULL,
    target_id VARCHAR(128) NOT NULL,
    status ENUM('candidate','blocked','deleted','failed') NOT NULL,
    reason VARCHAR(255) NULL,
    attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_retention_item_target (retention_run_id, data_type, target_id),
    KEY idx_retention_item_status (tenant_id, retention_run_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE retention_policy_projection (
    tenant_id BINARY(16) NOT NULL,
    data_type VARCHAR(64) NOT NULL,
    retention_days INT UNSIGNED NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT UNSIGNED NOT NULL DEFAULT 1,
    updated_by BINARY(16) NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (tenant_id, data_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE retention_runs (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    dry_run BOOLEAN NOT NULL,
    status ENUM('queued','running','completed','failed','cancelled') NOT NULL DEFAULT 'queued',
    requested_by BINARY(16) NOT NULL,
    candidate_count BIGINT UNSIGNED NOT NULL DEFAULT 0,
    deleted_count BIGINT UNSIGNED NOT NULL DEFAULT 0,
    error_message VARCHAR(1000) NULL,
    attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
    available_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    locked_by BINARY(16) NULL,
    locked_until TIMESTAMP(6) NULL,
    started_at TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    completed_at TIMESTAMP(6) NULL,
    PRIMARY KEY (id),
    KEY idx_retention_run_status (status, available_at, locked_until, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE runtime_calls (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    execution_id BINARY(16) NOT NULL,
    node_execution_id BINARY(16) NOT NULL,
    attempt_id BINARY(16) NOT NULL,
    agent_run_id BINARY(16) NULL,
    iteration_index INT UNSIGNED NOT NULL DEFAULT 0,
    call_index INT UNSIGNED NOT NULL,
    call_kind ENUM('model', 'compaction', 'mcp_tool', 'rag', 'memory', 'sandbox') NOT NULL,
    idempotency_key VARCHAR(192) NOT NULL,
    request_fingerprint CHAR(64) NOT NULL,
    resource_type VARCHAR(32) NULL,
    resource_id BINARY(16) NULL,
    resource_version_id BINARY(16) NULL,
    tool_name_snapshot VARCHAR(255) NULL,
    side_effect VARCHAR(32) NOT NULL DEFAULT 'none',
    status ENUM('reserved', 'sent', 'succeeded', 'failed', 'cancelled', 'unknown') NOT NULL,
    reserved_input_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
    reserved_output_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
    reserved_cost_micros BIGINT UNSIGNED NOT NULL DEFAULT 0,
    input_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
    output_tokens BIGINT UNSIGNED NOT NULL DEFAULT 0,
    cost_micros BIGINT UNSIGNED NOT NULL DEFAULT 0,
    cost_currency CHAR(3) NULL,
    usage_estimated BOOLEAN NOT NULL DEFAULT FALSE,
    response_artifact_id BINARY(16) NULL,
    error_code VARCHAR(128) NULL,
    error_message VARCHAR(1000) NULL,
    started_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    ended_at TIMESTAMP(6) NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_runtime_call_idempotency (tenant_id, idempotency_key),
    KEY idx_runtime_call_node (tenant_id, node_execution_id, iteration_index, call_index),
    KEY idx_runtime_call_execution (tenant_id, execution_id),
    KEY idx_runtime_call_resource (tenant_id, resource_type, resource_id, started_at),
    KEY idx_runtime_call_tool_execution (tenant_id, call_kind, resource_id, execution_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE runtime_commands (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    command_type VARCHAR(64) NOT NULL,
    aggregate_type VARCHAR(64) NOT NULL,
    aggregate_id VARCHAR(128) NOT NULL,
    idempotency_key VARCHAR(192) NOT NULL,
    payload_json JSON NOT NULL,
    status ENUM('pending','processing','completed','failed') NOT NULL DEFAULT 'pending',
    available_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    locked_by BINARY(16) NULL,
    locked_until TIMESTAMP(6) NULL,
    attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
    result_json JSON NULL,
    error_code VARCHAR(128) NULL,
    error_message VARCHAR(1000) NULL,
    completed_at TIMESTAMP(6) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_runtime_command_idempotency (tenant_id, command_type, idempotency_key),
    KEY idx_runtime_commands_pending (status, available_at, locked_until, created_at),
    KEY idx_runtime_commands_aggregate (tenant_id, aggregate_type, aggregate_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE runtime_idempotency_keys (
    tenant_id BINARY(16) NOT NULL,
    scope VARCHAR(96) NOT NULL,
    idempotency_key VARCHAR(192) NOT NULL,
    request_hash VARCHAR(96) NOT NULL,
    status ENUM('processing', 'completed', 'failed') NOT NULL,
    response_json JSON NULL,
    expires_at TIMESTAMP(6) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (tenant_id, scope, idempotency_key),
    KEY idx_runtime_idempotency_expiry (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE runtime_service_heartbeats (
    tenant_id BINARY(16) NOT NULL,
    service_type ENUM('coordinator', 'worker', 'sandbox', 'trace_writer') NOT NULL,
    instance_id VARCHAR(160) NOT NULL,
    status ENUM('ready', 'degraded', 'unavailable') NOT NULL,
    detail_json JSON NOT NULL,
    heartbeat_at TIMESTAMP(6) NOT NULL,
    PRIMARY KEY (tenant_id, service_type, instance_id),
    KEY idx_runtime_heartbeat (tenant_id, service_type, heartbeat_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE sandbox_leases (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    execution_id BINARY(16) NOT NULL,
    node_execution_id BINARY(16) NOT NULL,
    attempt_id BINARY(16) NOT NULL,
    worker_lease_token BINARY(16) NOT NULL,
    sandbox_id VARCHAR(255) NULL,
    lease_token_hash CHAR(64) NOT NULL,
    profile_version_id BINARY(16) NOT NULL,
    idempotency_key VARCHAR(192) NOT NULL,
    status ENUM('creating', 'ready', 'running', 'interrupting', 'terminating', 'terminated', 'orphaned', 'failed') NOT NULL,
    endpoint_auth_key_id VARCHAR(64) NULL,
    endpoint_auth_nonce VARBINARY(32) NULL,
    endpoint_auth_ciphertext MEDIUMBLOB NULL,
    expires_at TIMESTAMP(6) NOT NULL,
    heartbeat_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    termination_attempts INT UNSIGNED NOT NULL DEFAULT 0,
    last_error VARCHAR(1000) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    terminated_at TIMESTAMP(6) NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_sandbox_lease_idempotency (tenant_id, idempotency_key),
    UNIQUE KEY uq_sandbox_lease_token (lease_token_hash),
    KEY idx_sandbox_lease_reaper (status, expires_at, heartbeat_at),
    KEY idx_sandbox_lease_attempt (tenant_id, attempt_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE sandbox_workspaces (
    workspace_id BINARY(16) NOT NULL,
    identity_hash CHAR(64) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    application_id BINARY(16) NULL,
    session_key VARCHAR(255) NOT NULL,
    stable_agent_node_key VARCHAR(255) NOT NULL,
    profile_version_id VARCHAR(191) NOT NULL,
    profile_json JSON NOT NULL,
    sandbox_id VARCHAR(255) NULL,
    status ENUM('creating','active','releasing','expired','unknown_outcome') NOT NULL DEFAULT 'creating',
    lease_id BINARY(16) NULL,
    attempt_id BINARY(16) NULL,
    worker_id BINARY(16) NULL,
    fencing_token BIGINT UNSIGNED NOT NULL DEFAULT 0,
    lease_expires_at TIMESTAMP(6) NULL,
    workspace_expires_at TIMESTAMP(6) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (workspace_id),
    UNIQUE KEY uq_sandbox_workspace_identity (identity_hash),
    KEY idx_sandbox_workspace_reaper (status, workspace_expires_at, lease_expires_at),
    KEY idx_sandbox_workspace_tenant (tenant_id, application_id, session_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE sandbox_process_sessions (
    process_session_id BINARY(16) NOT NULL,
    identity_hash CHAR(64) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    agent_run_id BINARY(16) NOT NULL,
    mcp_server_version_id BINARY(16) NOT NULL,
    sandbox_profile_version_id BINARY(16) NOT NULL,
    profile_json JSON NOT NULL,
    command_json JSON NOT NULL,
    credential_refs_json JSON NOT NULL,
    sandbox_id VARCHAR(255) NULL,
    provider_operation_id VARCHAR(255) NULL,
    provider_output_offset BIGINT UNSIGNED NOT NULL DEFAULT 0,
    status ENUM('acquiring','starting','running','interrupting','terminating','exited','failed','unknown_outcome','expired') NOT NULL,
    lease_id BINARY(16) NOT NULL,
    attempt_id BINARY(16) NOT NULL,
    worker_id BINARY(16) NOT NULL,
    fencing_token BIGINT UNSIGNED NOT NULL,
    lease_expires_at TIMESTAMP(6) NOT NULL,
    process_expires_at TIMESTAMP(6) NOT NULL,
    exit_code BIGINT NULL,
    last_error VARCHAR(1000) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (process_session_id),
    UNIQUE KEY uq_sandbox_process_identity (identity_hash),
    KEY idx_sandbox_process_reaper (status, process_expires_at, lease_expires_at),
    KEY idx_sandbox_process_run (tenant_id, agent_run_id, mcp_server_version_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE sandbox_process_frames (
    process_session_id BINARY(16) NOT NULL,
    sequence BIGINT UNSIGNED NOT NULL,
    stream ENUM('stdout','stderr') NOT NULL,
    payload_json JSON NULL,
    artifact_id BINARY(16) NULL,
    truncated BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (process_session_id, sequence),
    KEY idx_sandbox_process_frame_artifact (artifact_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE side_effect_confirmations (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    execution_id BINARY(16) NOT NULL,
    node_execution_id BINARY(16) NOT NULL,
    checkpoint_id BINARY(16) NULL,
    actor_user_id BINARY(16) NOT NULL,
    decision ENUM('execute', 'reuse_output', 'dry_run') NOT NULL,
    idempotency_key VARCHAR(192) NOT NULL,
    detail_json JSON NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_side_effect_decision (tenant_id, execution_id, node_execution_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE tenant_policy_projection (
    tenant_id BINARY(16) NOT NULL,
    policy_version BIGINT UNSIGNED NOT NULL,
    policy_json JSON NOT NULL,
    applied_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (tenant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE tenant_admission (
    tenant_id BINARY(16) NOT NULL,
    status ENUM('active','disabled') NOT NULL,
    admission_epoch BIGINT UNSIGNED NOT NULL,
    policy_version BIGINT UNSIGNED NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (tenant_id),
    CONSTRAINT chk_tenant_admission_epoch CHECK (admission_epoch > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE trace_outbox (
    event_id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    execution_id BINARY(16) NOT NULL,
    payload_json JSON NOT NULL,
    status ENUM('pending','streamed','failed') NOT NULL DEFAULT 'pending',
    available_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    locked_by BINARY(16) NULL,
    locked_until TIMESTAMP(6) NULL,
    fencing_token BIGINT UNSIGNED NOT NULL DEFAULT 0,
    attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
    last_error VARCHAR(1000) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (event_id),
    KEY idx_trace_outbox_claim (status, available_at, locked_until, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE trigger_bindings (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    application_id BINARY(16) NOT NULL,
    application_deployment_id BINARY(16) NOT NULL,
    workflow_version_id BINARY(16) NOT NULL,
    node_id VARCHAR(128) NOT NULL,
    trigger_kind ENUM('webhook','schedule','poll','lifecycle') NOT NULL,
    configuration_json JSON NOT NULL,
    status ENUM('activating','active','deactivating','disabled','failed') NOT NULL,
    next_poll_at TIMESTAMP(6) NULL,
    last_poll_at TIMESTAMP(6) NULL,
    locked_by BINARY(16) NULL,
    locked_until TIMESTAMP(6) NULL,
    last_error VARCHAR(1000) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_trigger_binding_node (tenant_id, application_deployment_id, node_id, trigger_kind),
    KEY idx_trigger_binding_scan (status, trigger_kind, next_poll_at, locked_until)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE worker_capabilities (
    instance_id VARCHAR(160) NOT NULL,
    capability VARCHAR(64) NOT NULL,
    node_protocol_version VARCHAR(32) NOT NULL,
    ir_schema_versions_json JSON NOT NULL,
    compiler_version_min VARCHAR(64) NOT NULL,
    compiler_version_max VARCHAR(64) NOT NULL,
    manifest_hashes_json JSON NOT NULL,
    status ENUM('ready','draining','unavailable') NOT NULL DEFAULT 'ready',
    heartbeat_at TIMESTAMP(6) NOT NULL,
    PRIMARY KEY (instance_id, capability),
    KEY idx_worker_capability_ready (capability, status, heartbeat_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE worker_leases (
    node_attempt_id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    node_execution_id BINARY(16) NOT NULL,
    lease_token BINARY(16) NOT NULL,
    worker_instance_id VARCHAR(160) NOT NULL,
    capability ENUM('builtin', 'declarative_http') NOT NULL,
    acquired_at TIMESTAMP(6) NOT NULL,
    heartbeat_at TIMESTAMP(6) NOT NULL,
    expires_at TIMESTAMP(6) NOT NULL,
    released_at TIMESTAMP(6) NULL,
    PRIMARY KEY (node_attempt_id),
    KEY idx_worker_lease_reaper (expires_at, released_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE workflow_context_patches (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    execution_id BINARY(16) NOT NULL,
    node_execution_id BINARY(16) NOT NULL,
    attempt_id BINARY(16) NOT NULL,
    patch_index INT UNSIGNED NOT NULL,
    operation_key VARCHAR(32) NOT NULL,
    context_path VARCHAR(512) NOT NULL,
    value_json JSON NOT NULL,
    context_version_before BIGINT UNSIGNED NOT NULL,
    context_version_after BIGINT UNSIGNED NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_workflow_context_patch (tenant_id, node_execution_id, patch_index),
    KEY idx_workflow_context_patch_execution (tenant_id, execution_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE workflow_deployment_heads (
    tenant_id BINARY(16) NOT NULL,
    workflow_id BINARY(16) NOT NULL,
    environment_id BINARY(16) NOT NULL,
    active_deployment_id BINARY(16) NOT NULL,
    version BIGINT UNSIGNED NOT NULL DEFAULT 1,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (tenant_id, workflow_id, environment_id),
    UNIQUE KEY uq_workflow_active_deployment (active_deployment_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE workflow_deployments (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    workflow_id BINARY(16) NOT NULL,
    environment_id BINARY(16) NOT NULL,
    workflow_version_id BINARY(16) NOT NULL,
    sequence_number BIGINT UNSIGNED NOT NULL,
    status ENUM('active', 'superseded', 'rolled_back') NOT NULL DEFAULT 'active',
    source ENUM('publish', 'rollback') NOT NULL DEFAULT 'publish',
    created_by BINARY(16) NOT NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_workflow_deployment_sequence (tenant_id, workflow_id, environment_id, sequence_number),
    KEY idx_workflow_deployment_history (tenant_id, workflow_id, environment_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE workflow_executions (
    id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    workflow_id BINARY(16) NOT NULL,
    workflow_version_id BINARY(16) NOT NULL,
    invocation_id BINARY(16) NULL,
    session_id BINARY(16) NULL,
    trace_id BINARY(16) NOT NULL,
    trigger_type VARCHAR(32) NOT NULL,
    status ENUM('created', 'queued', 'running', 'waiting', 'waiting_approval', 'suspended', 'succeeded', 'failed', 'cancelled', 'timed_out') NOT NULL,
    started_at TIMESTAMP(6) NOT NULL,
    ended_at TIMESTAMP(6) NULL,
    duration_ms BIGINT UNSIGNED NULL,
    cost_micros BIGINT UNSIGNED NOT NULL DEFAULT 0,
    error_code VARCHAR(128) NULL,
    error_message VARCHAR(1000) NULL,
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    UNIQUE KEY uq_workflow_execution_trace (tenant_id, trace_id),
    KEY idx_workflow_executions_list (tenant_id, status, started_at),
    KEY idx_workflow_executions_workflow (tenant_id, workflow_id, started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE service_identity_projection (
    identity_id BINARY(16) NOT NULL,
    tenant_id BINARY(16) NOT NULL,
    workflow_id BINARY(16) NOT NULL,
    policy_epoch BIGINT UNSIGNED NOT NULL,
    status ENUM('active','disabled') NOT NULL,
    capabilities_json JSON NOT NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (identity_id),
    KEY idx_service_identity_workflow (tenant_id, workflow_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
